css:
@font-face {
	font-family: "Montserrat";
	font-weight: 400 800;
	src: url("/assets/afmco/css/fonts/montserrat-400-800-latin.woff2") format("woff2");
	unicode-range: U+0000-00FF, U+2013-2014, U+2018-201E;
}

@font-face {
	font-family: "Tajawal";
	font-weight: 700;
	src: url("/assets/afmco/css/fonts/tajawal-700-arabic.woff2") format("woff2");
	unicode-range: U+0600-06FF, U+0750-077F, U+200C-200E, U+FB50-FDFF, U+FE70-FEFF;
}

@page {
	size: 50mm 25mm;
	margin: 0;
}

.print-format {
	page-width: 50mm;
	page-height: 25mm;
	margin-top: 0mm;
	margin-bottom: 0mm;
	margin-left: 0mm;
	margin-right: 0mm;
	padding: 0;
	width: 50mm;
	max-width: 50mm;
	min-height: 0;
}

.print-format .afm-albl {
	position: relative;
	box-sizing: border-box;
	width: 50mm;
	height: 25mm;
	overflow: hidden;
	direction: ltr;
	color: #072B1A;
	background-color: #FFFFFF;
	font-family: "Montserrat", "Tajawal", "Segoe UI", Tahoma, Arial, sans-serif;
	page-break-after: always;
	break-after: page;
	-webkit-print-color-adjust: exact;
	print-color-adjust: exact;
}

.print-format .afm-albl-qr {
	position: absolute;
	top: 2.75mm;
	left: 2mm;
	width: 19.5mm;
	height: 19.5mm;
}

.print-format .afm-albl-rule {
	position: absolute;
	top: 3mm;
	left: 22.75mm;
	width: 0.3mm;
	height: 19mm;
	background-color: #00844E;
}

.print-format .afm-albl-side {
	position: absolute;
	top: 2.5mm;
	left: 24.25mm;
	width: 23.75mm;
	height: 20mm;
	overflow: hidden;
}

.print-format .afm-albl-logo {
	display: block;
	height: 8mm;
	width: auto;
	max-width: none;
	object-fit: contain;
	margin-left: -0.75mm;
}

.print-format .afm-albl-name {
	position: absolute;
	top: 9mm;
	left: 0;
	width: 23.75mm;
	max-height: 6mm;
	overflow: hidden;
	word-wrap: break-word;
	text-align: start;
	font-size: 6.5pt;
	line-height: 3mm;
	font-weight: 700;
}

.print-format .afm-albl-code {
	position: absolute;
	left: 0;
	bottom: 0;
	width: 23.75mm;
	padding-top: 0.8mm;
	border-top: 0.2mm solid #00844E;
	line-height: 2.8mm;
	white-space: nowrap;
	overflow: hidden;
	direction: ltr;
	font-size: 5.6pt;
	font-weight: 600;
	letter-spacing: 0.05mm;
}
